const crypto = require('crypto');
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const controlUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('command_secret_not_configured');
if (!/\/api\/v1\/automation\/control\/receipt$/.test(controlUrl)) throw new Error('control_url_invalid');
const executionId = String($execution.id || '').trim();
if (!executionId) throw new Error('missing_execution_id');
const body = JSON.stringify({schema_version:1,action:'MIRROR_APPROVED_CANONICAL_MEDIA',execution_id:executionId.slice(0,120),occurred_at:new Date().toISOString(),limit:3});
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto.createHmac('sha256',secret).update(timestamp + '.' + body,'utf8').digest('hex');
return [{json:{mirror_url:controlUrl.replace(/\/control\/receipt$/, '/commands/storage/mirror-approved-media'),mirror_body:body,mirror_timestamp:timestamp,mirror_signature:signature}}];

const response = $input.first().json || {};
const status = Number(response.statusCode || 0);
if (status < 200 || status >= 300) throw new Error('r2_mirror_http_' + status);
const body = response.body || {};
if (body.accepted !== true || typeof body.mirrored !== 'number' || Number(body.failed || 0) !== 0) throw new Error('r2_mirror_receipt_not_verified');
return [{json:{execution_id:body.execution_id,mirrored:body.mirrored,skipped:body.skipped,examined:body.examined,remaining_possible:body.remaining_possible}}];
